-- 001_create_users.sql
-- Migration: create the `users` table for FinSight AI
-- ----------------------------------------------------
-- This table stores authentication credentials, role based access control
-- information and per‑user UI preferences.
-- It is designed for production use with:
--   * UUID primary key generated by pgcrypto
--   * Unique, case‑insensitive email address
--   * Secure password hash (bcrypt, argon2, etc.) stored as text
--   * Enumerated role with a CHECK constraint
--   * JSONB column for extensible user preferences (theme, language, …)
--   * Auditable timestamps (created_at, updated_at) and soft‑delete support
--   * Indexes to support common lookup patterns

-- Ensure the pgcrypto extension is available for UUID generation.
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- -------------------------------------------------------------------------
-- Table definition
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
    id              UUID            PRIMARY KEY DEFAULT gen_random_uuid(),
    email           VARCHAR(255)    NOT NULL,
    password_hash   TEXT            NOT NULL,
    role            VARCHAR(20)     NOT NULL DEFAULT 'user',
    preferences     JSONB           NOT NULL DEFAULT '{}'::jsonb,
    created_at      TIMESTAMPTZ     NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ     NOT NULL DEFAULT now(),
    deleted_at      TIMESTAMPTZ,

    CONSTRAINT uq_users_email UNIQUE (LOWER(email)),
    CONSTRAINT chk_users_role CHECK (role IN ('admin', 'user'))
);

-- -------------------------------------------------------------------------
-- Indexes
-- -------------------------------------------------------------------------
-- Index on role for quick RBAC look‑ups
CREATE INDEX IF NOT EXISTS idx_users_role ON users (role);

-- Index on deleted_at to speed up soft‑delete queries
CREATE INDEX IF NOT EXISTS idx_users_deleted_at ON users (deleted_at);

-- -------------------------------------------------------------------------
-- Trigger to keep `updated_at` in sync
-- -------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION trigger_set_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS set_timestamp ON users;
CREATE TRIGGER set_timestamp
BEFORE UPDATE ON users
FOR EACH ROW
EXECUTE FUNCTION trigger_set_timestamp();

